-- Read-only verification of the retained shared acceptance fixture.
-- The reconstructed digest excludes the new learner and reverses only the one
-- expected teacher credit for comparison with the pre-upgrade snapshot.
with fixture as (select e.status, e.learner_id, e.teacher_id, l.credits_balance as learner_balance, t.credits_balance as teacher_balance from public.exchanges e join public.skills s on s.id=e.skill_id join public.profiles l on l.id=e.learner_id join public.profiles t on t.id=e.teacher_id where s.title='Acceptance Test Guitar QLNRFA') select jsonb_build_object('matching_exchanges',(select count(*) from fixture),'statuses',(select jsonb_agg(status) from fixture),'learner_balance',(select learner_balance from fixture),'teacher_balance',(select teacher_balance from fixture),'combined_balance',(select learner_balance+teacher_balance from fixture),'global_credit_total',(select sum(credits_balance) from public.profiles),'pretest_balance_digest_reconstructed',(select md5(string_agg(p.id::text || ':' || (p.credits_balance-case when p.id=f.teacher_id then 1 else 0 end)::text,',' order by p.id)) from public.profiles p cross join fixture f where p.id<>f.learner_id)) as settlement_verification;
